def add_months(y, m, d, n):
    # Calculate total months
    total_months = y * 12 + (m - 1) + n
    # Handle negative total_months correctly
    new_y = total_months // 12
    new_m = total_months % 12 + 1

    # Get the last day of the target month
    if new_m == 12:
        next_y, next_m = new_y + 1, 1
    else:
        next_y, next_m = new_y, new_m + 1

    # Calculate last day of new_m in new_y
    # Days in each month
    def days_in_month(year, month):
        if month in (1, 3, 5, 7, 8, 10, 12):
            return 31
        elif month in (4, 6, 9, 11):
            return 30
        else:  # February
            if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
                return 29
            else:
                return 28

    last_day = days_in_month(new_y, new_m)
    new_d = min(d, last_day)

    return (new_y, new_m, new_d)
